    """
    scripts_dir = str(Path(self.build_outputs_dir) / 'scripts')
    os.makedirs(scripts_dir, exist_ok=True)

    for item, new_name in constants.CONTEXT_FILES.items():
        # HACK: new dynamic base/builder
